function applyStaticContactOcclusion(root: THREE.Group): void {
  const data = STATIC_AO_DATA, pixels = new Uint8Array(data.size * data.size * 4);
  const encoded = atob(data.runBytes); let pixel = 0;
  for (let i = 0; i < encoded.length; i += 3) {
    const count = encoded.charCodeAt(i) + (encoded.charCodeAt(i + 1) << 8), v = encoded.charCodeAt(i + 2);
    for (let j = 0; j < count; j++) { pixels[pixel++] = v; pixels[pixel++] = v; pixels[pixel++] = v; pixels[pixel++] = 255; }
  }
  if (pixel !== pixels.length) throw new Error('Static AO atlas decode length mismatch');
  const atlas = new THREE.DataTexture(pixels, data.size, data.size, THREE.RGBAFormat);
  atlas.name = 'static-contact-occlusion'; atlas.colorSpace = THREE.NoColorSpace; atlas.channel = 1;
  atlas.flipY = false; atlas.generateMipmaps = false; atlas.minFilter = THREE.LinearFilter; atlas.magFilter = THREE.LinearFilter;
  atlas.needsUpdate = true;
  atlas.userData = { source: 'quality-above95/round10/static-ao-bake.json', method: 'static procedural triangle cosine-ray visibility', rayRadiusMeters: 1.6, samplesPerTexel: 48 };
  const meshes = (root.userData.sculptRuntime as any).byId.meshes as Record<string, THREE.Mesh>;
  const targets = new Set(data.targets.map(t => t.id)), externalMaterials = new Set<THREE.Material>();
  for (const [id, mesh] of Object.entries(meshes)) if (!targets.has(id)) externalMaterials.add(mesh.material as THREE.Material);
  const clones = new Map<THREE.Material, THREE.MeshPhysicalMaterial>();
  for (const target of data.targets) {
    const mesh = meshes[target.id]; if (!mesh || (mesh as THREE.InstancedMesh).isInstancedMesh) throw new Error('Missing static AO mesh: ' + target.id);
    const old = mesh.geometry, geometry = old.index ? old.toNonIndexed() : old.clone();
    const world = geometry.clone().applyMatrix4(mesh.matrixWorld), positions = world.attributes.position;
    let checksum = 2166136261;
    for (let i = 0; i < positions.count; i++) for (let k = 0; k < 3; k++) {
      checksum = Math.imul(checksum ^ Math.round(positions.array[i * 3 + k] * 1e6), 16777619) >>> 0;
    }
    world.dispose();
    if (positions.count !== target.vertices || checksum !== target.worldPositionChecksum) throw new Error('Static AO geometry changed; rebake ' + target.id);
    geometry.userData = { ...old.userData };
    if (old.userData.physicalParts) geometry.userData.physicalParts = old.userData.physicalParts.map((r: any) => ({ ...r, firstVertex: r.firstIndex, vertexCount: r.indexCount }));
    geometry.setAttribute('uv1', new THREE.Float32BufferAttribute(target.uv, 2));
    geometry.userData.staticAo = { atlas: atlas.name, channel: 1, sourceTriangleChecksum: checksum };
    mesh.geometry = geometry; old.dispose();
    let material = mesh.material as THREE.MeshPhysicalMaterial;
    if (externalMaterials.has(material)) {
      if (!clones.has(material)) { const clone = material.clone(); clone.name = (material.name || target.id) + '-static-ao'; clones.set(material, clone); }
      material = clones.get(material)!; mesh.material = material;
    }
    material.aoMap = atlas; material.aoMapIntensity = 1; material.needsUpdate = true;
  }
  root.userData.staticAo = { texture: atlas.name, targetIds: [...targets], excludedPhysicalGlassAndWash: true, geometryOnly: true, source: 'quality-above95/round10/static-ao-bake.json' };
}

/* ------------------------------------------------------------------ thaikit entry point */

/**
 * thaikit entry point. The registry records `createObjectModel` as the export and calls it with
 * (spec, options). `spec` is accepted and attached for host-side inspection -- the reconstruction
 * data already lives in this module, so it is deliberately not a second source of truth.
 */
export function createObjectModel(spec?: unknown, options: ProceduralModelOptions = {}): THREE.Group {
  const root = createBangkokApartmentBlockModel(options);
  if (spec !== undefined && spec !== null) root.userData.sculptSpec = spec;

  const rt = root.userData.sculptRuntime as Record<string, any> | undefined;
  if (rt) {
    const nodes = (rt.nodes ?? {}) as Record<string, THREE.Object3D>;

    // Pivots: ONE. Static landmark geometry -- nothing opens, turns or swings. A named pivot is a
    // promise that a part turns on it, and a prop that declares pivots it has no mechanisms for
    // has described a machine that does not exist.
    const pivots: THREE.Object3D[] = [];
    const rootPivot = new THREE.Object3D();
    rootPivot.name = 'root';
    rootPivot.position.set(0, 0, 0);
    rootPivot.userData.actionProfile = {
      animationRole: 'root',
      pivot: { mode: 'custom', localPosition: [0, 0, 0], axis: [0, 1, 0], name: 'root' },
    };
    root.add(rootPivot);
    pivots.push(rootPivot);

    // Sockets: NONE. Nothing attaches to this prop and nothing is emitted from it.

    // Colliders are plain DATA, not Object3D, so they carry no .name of their own. Give each the
    // id of the component it owns and drop the empty ones -- a nameless empty proxy in the
    // runtime list reads as a physics shape that exists and does nothing.
    const colliders = Object.entries((rt.colliders ?? {}) as Record<string, any>)
      .filter(([, c]) => c && typeof c === 'object' && Object.keys(c).length > 0)
      .map(([id, c]) => ({ name: id, ...(c as object) }));

    // Destruction groups: this prop declares NONE, and promotion checks built against declared as
    // an equality in BOTH directions. Derived rather than assumed empty, so a component that
    // somehow carried a fractureGroup fails the gate loudly instead of being dropped here.
    const grouped = new Map<string, THREE.Object3D[]>();
    for (const [name, members] of Object.entries((rt.destructionGroups ?? {}) as Record<string, THREE.Object3D[]>)) {
      grouped.set(name, [...members]);
    }
    for (const node of Object.values(nodes)) {
      const group = (node as any)?.userData?.actionProfile?.destruction?.fractureGroup;
      if (typeof group !== 'string' || !group) continue;
      if (!grouped.has(group)) grouped.set(group, []);
      grouped.get(group)!.push(node);
    }

    root.userData.sculptRuntime = {
      ...rt,
      // A COUNT, not the Record. thaikit's harness returns this field straight across the
      // puppeteer bridge and its registry field is a number; a Record of Object3D is circular and
      // fails to serialise, which surfaces as the whole stats object arriving undefined. The
      // Record stays reachable under byId.
      nodes: Object.keys(nodes).length,
      pivots,
      sockets: Object.values((rt.sockets ?? {}) as Record<string, THREE.Object3D>),
      colliders,
      destructionGroups: [...grouped.entries()].map(([name, members]) => ({ name, members })),
      byId: { nodes, meshes: rt.meshes ?? {}, sockets: rt.sockets ?? {} },
    };
  }
  root.updateMatrixWorld(true);
  applyStaticContactOcclusion(root);
  return root;
}

export function createModel(options: ProceduralModelOptions = {}): THREE.Group { return createObjectModel(undefined, options); }
